import unittest
from candidate import total_match

class TestTotalMatch(unittest.TestCase):
    def test_empty_lists(self):
        self.assertEqual(total_match([], []), [])

    def test_case_insensitive_strings(self):
        self.assertEqual(total_match(['hi', 'admin'], ['hI', 'Hi']), ['hI', 'Hi'])

    def test_different_lengths(self):
        self.assertEqual(total_match(['hi', 'admin'], ['hi', 'hi', 'admin', 'project']), ['hi', 'admin'])

    def test_single_element_lists(self):
        self.assertEqual(total_match(['4'], ['1', '2', '3', '4', '5']), ['4'])

    def test_equal_lengths(self):
        self.assertEqual(total_match(['a', 'bb'], ['ab', 'c']), ['a', 'bb'])

    def test_non_string_elements(self):
        with self.assertRaises(TypeError):
            total_match([1, 2], ['a', 'b'])

    def test_empty_first_list(self):
        self.assertEqual(total_match([], ['a', 'b']), [])

    def test_empty_second_list(self):
        self.assertEqual(total_match(['a', 'b'], []), ['a', 'b'])

    def test_identical_lists(self):
        self.assertEqual(total_match(['same', 'list'], ['same', 'list']), ['same', 'list'])

    def test_mixed_case_and_numbers(self):
        self.assertEqual(total_match(['a1', 'B2'], ['a1b2', 'X']), ['a1', 'B2'])

    def test_lists_with_special_characters(self):
        self.assertEqual(total_match(['!@#', 'test'], ['test!', '!@#']), ['!@#', 'test'])

    def test_lists_with_empty_strings(self):
        self.assertEqual(total_match(['', 'test'], ['test', '']), ['', 'test'])

    def test_lists_with_whitespace(self):
        self.assertEqual(total_match(['  ', 'test'], ['test', '  ']), ['test', 'test'])

    def test_lists_with_unicode_characters(self):
        self.assertEqual(total_match(['café', 'résumé'], ['résumé', 'café']), ['café', 'résumé'])

    def test_lists_with_very_long_strings(self):
        long_str = 'a' * 1000
        self.assertEqual(total_match([long_str], ['a' * 1001]), [long_str])
